import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * File-backed credential store for the Task Management System.
 *
 * <p>Credentials are persisted as one {@code username:[secret redacted]
 * {@code data/users.txt}. The directory and file are created on demand the first time a
 * user registers, so the program never fails on a fresh workspace. Malformed or blank
 * lines are ignored so a partially written file cannot crash the application.</p>
 */
public class UserStore {

    /** Parent directory used for persisted application data. */
    private static final String DATA_DIR = "data";

    private final String filePath;
    private final Map<String, String> users = new LinkedHashMap<String, String>();

    public UserStore(String filePath) {
        this.filePath = filePath;
    }

    /** Loads persisted users from disk (no-op when the file does not exist yet). */
    public void load() {
        users.clear();
        File file = new File(filePath);
        if (!file.exists()) {
            return;
        }
        BufferedReader reader = null;
        try {
            reader = new BufferedReader(new FileReader(file));
            String line;
            while ((line = reader.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                int sep = line.indexOf(':');
                if (sep <= 0) {
                    continue;
                }
                String username = line.substring(0, sep).trim();
                String password = [secret redacted]
                if (!username.isEmpty()) {
                    users.put(username, password);
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read credentials file: " + e.getMessage());
        } finally {
            if (reader != null) {
                try {
                    reader.close();
                } catch (IOException ignored) {
                    // Nothing sensible to do on close failure.
                }
            }
        }
    }

    /** @return true when a user with the given name is already stored. */
    public boolean exists(String username) {
        return users.containsKey(username);
    }

    /** @return true when the username/password pair matches a stored user. */
    public boolean validate(String username, String password) {
        String stored = users.get(username);
        return stored != null && stored.equals(password);
    }

    /**
     * Adds a new user and persists the store to disk.
     *
     * @return true on success, false when the user already exists or saving failed.
     */
    public boolean register(String username, String password) {
        if (exists(username)) {
            return false;
        }
        users.put(username, password);
        return save();
    }

    /** @return the number of known users. */
    public int size() {
        return users.size();
    }

    /** Writes the whole store to disk, creating the data directory if needed. */
    private boolean save() {
        File dir = new File(DATA_DIR);
        if (!dir.exists() && !dir.mkdirs() && !dir.exists()) {
            System.out.println("Error: could not create data directory.");
            return false;
        }
        BufferedWriter writer = null;
        try {
            writer = new BufferedWriter(new FileWriter(filePath));
            for (Map.Entry<String, String> entry : users.entrySet()) {
                writer.write(entry.getKey() + ":[secret redacted]
                writer.newLine();
            }
            writer.flush();
            return true;
        } catch (IOException e) {
            System.out.println("Error: could not save credentials: " + e.getMessage());
            return false;
        } finally {
            if (writer != null) {
                try {
                    writer.close();
                } catch (IOException ignored) {
                    // Nothing sensible to do on close failure.
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Task Management System - Subtask 1: CLI user registration and login layer.
 *
 * <p>Entry point: {@code Main}. Compile from this directory with
 * {@code javac -d bin *.java} and run with {@code java -cp bin Main}.</p>
 *
 * <p>Usage / expected prompts:</p>
 * <pre>
 * Welcome menu (shown on every launch):
 *   1. Register
 *   2. Login
 *   3. Exit
 *
 * Register:  prompts for "Enter username", "Enter password" and "Confirm password".
 *            Empty values, duplicate usernames and mismatched confirmations are
 *            rejected and the flow re-prompts until valid. On success it prints
 *            "Registration successful" and persists the user to data/users.txt.
 *
 * Login:     prompts for "Enter username" and "Enter password". A bad username or
 *            password prints "Login failed: [secret redacted]
 *            followed by the "Try again? (y/n):" prompt so the user can retry or
 *            return to the welcome menu. Success prints "Login successful".
 *
 * Main menu (after login):
 *   1. View Tasks   2. Logout   3. Exit
 *   Logout returns to the welcome menu; Exit prints "Goodbye" and terminates.
 *
 * If standard input ends (EOF), the program exits cleanly instead of crashing.
 * </pre>
 */
public class Main {

    private static final String USERS_FILE = "data/users.txt";

    private final UserStore store;
    private final BufferedReader in;
    private boolean eof = false;

    public Main(UserStore store, BufferedReader in) {
        this.store = store;
        this.in = in;
    }

    public static void main(String[] args) {
        UserStore store = new UserStore(USERS_FILE);
        // Reload persisted users so previously registered accounts can log in.
        store.load();

        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        Main app = new Main(store, reader);
        app.run();
    }

    /** Top-level welcome loop; always exits gracefully with a goodbye message. */
    public void run() {
        while (true) {
            if (eof) {
                break;
            }
            printWelcomeMenu();
            String choice = readLine();
            if (choice == null) {
                break;
            }
            String option = normalize(choice);
            if ("1".equals(option) || "register".equals(option) || "r".equals(option)) {
                registerFlow();
            } else if ("2".equals(option) || "login".equals(option) || "l".equals(option)) {
                if (loginFlow()) {
                    authenticatedMenu();
                }
            } else if ("3".equals(option) || "exit".equals(option) || "quit".equals(option)
                    || "q".equals(option) || "e".equals(option)) {
                break;
            } else {
                System.out.println("Invalid option. Please try again.");
            }
        }
        System.out.println("Goodbye");
    }

    private void printWelcomeMenu() {
        System.out.println();
        System.out.println("===== Welcome to the Task Management System =====");
        System.out.println("1. Register");
        System.out.println("2. Login");
        System.out.println("3. Exit");
        System.out.print("Please choose an option (1-3): ");
    }

    /** Collects and validates registration input until a user is created. */
    private void registerFlow() {
        System.out.println();
        System.out.println("===== Registration =====");
        while (true) {
            if (eof) {
                return;
            }
            System.out.print("Enter username: ");
            String usernameLine = readLine();
            if (usernameLine == null) {
                return;
            }
            String username = usernameLine.trim();
            if (username.isEmpty()) {
                System.out.println("Error: username must not be empty.");
                continue;
            }
            if (store.exists(username)) {
                System.out.println("Error: username already exists. Please choose another.");
                continue;
            }

            System.out.print("Enter password: [secret redacted]
            String passwordLine = [secret redacted]
            if (passwordLine =[secret redacted]
                return;
            }
            String password = [secret redacted]
            if (password.trim().isEmpty()) {
                System.out.println("Error: password must not be empty.");
                continue;
            }

            System.out.print("Confirm password: [secret redacted]
            String confirmLine = readLine();
            if (confirmLine == null) {
                return;
            }
            if (!password.equals(confirmLine)) {
                System.out.println("Error: passwords do not match. Please try again.");
                continue;
            }

            if (store.register(username, password)) {
                System.out.println("Registration successful. You can now log in.");
            } else {
                System.out.println("Error: registration failed, username may already exist.");
            }
            return;
        }
    }

    /**
     * Prompts for credentials, retrying on failure.
     *
     * @return true when login succeeded, false on failure/EOF/return-to-menu.
     */
    private boolean loginFlow() {
        System.out.println();
        System.out.println("===== Login =====");
        while (true) {
            if (eof) {
                return false;
            }
            System.out.print("Enter username: ");
            String usernameLine = readLine();
            if (usernameLine == null) {
                return false;
            }
            String username = usernameLine.trim();

            System.out.print("Enter password: [secret redacted]
            String passwordLine = [secret redacted]
            if (passwordLine =[secret redacted]
                return false;
            }

            if (store.validate(username, passwordLine)) {
                System.out.println("Login successful. Welcome, " + username + "!");
                return true;
            }

            System.out.println("Login failed: invalid username or wrong password.");
            System.out.print("Try again? (y/n): ");
            String answer = readLine();
            if (answer == null) {
                return false;
            }
            String normalized = normalize(answer);
            if (!"y".equals(normalized) && !"yes".equals(normalized)) {
                return false;
            }
        }
    }

    /** Menu shown to authenticated users; supports logout and graceful exit. */
    private void authenticatedMenu() {
        while (true) {
            if (eof) {
                return;
            }
            System.out.println();
            System.out.println("===== Main Menu =====");
            System.out.println("1. View Tasks");
            System.out.println("2. Logout");
            System.out.println("3. Exit");
            System.out.print("Please choose an option (1-3): ");
            String choice = readLine();
            if (choice == null) {
                return;
            }
            String option = normalize(choice);
            if ("1".equals(option) || "view".equals(option) || "tasks".equals(option)) {
                System.out.println("No tasks available yet.");
            } else if ("2".equals(option) || "logout".equals(option)) {
                System.out.println("Logged out.");
                return;
            } else if ("3".equals(option) || "exit".equals(option) || "quit".equals(option)
                    || "q".equals(option) || "e".equals(option)) {
                return;
            } else {
                System.out.println("Invalid option. Please try again.");
            }
        }
    }

    /**
     * Reads one line of input.
     *
     * @return the line, or null when standard input has ended (EOF).
     */
    private String readLine() {
        try {
            String line = in.readLine();
            if (line == null) {
                eof = true;
            }
            return line;
        } catch (IOException e) {
            eof = true;
            return null;
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase();
    }
}

