/**
 * A single task belonging to a user in the Task Management System.
 *
 * <p>A task has a numeric id (unique within its owner's file), a title, an optional
 * description, creation/update timestamps, and a status of {@code Pending} or
 * {@code Completed}. Instances are created and mutated through {@link TaskStore},
 * which is responsible for persistence.</p>
 */
public class Task {

    /** Status value for a task that still needs to be done. */
    public static final String STATUS_PENDING = "Pending";

    /** Status value for a finished task. */
    public static final String STATUS_COMPLETED = "Completed";

    private final int id;
    private String title;
    private String description;
    private String createdAt;
    private String updatedAt;
    private String status;

    public Task(int id, String title, String description, String createdAt,
                String updatedAt, String status) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
        this.status = status;
    }

    public int getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getCreatedAt() {
        return createdAt;
    }

    public String getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(String updatedAt) {
        this.updatedAt = updatedAt;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public boolean isCompleted() {
        return STATUS_COMPLETED.equalsIgnoreCase(status);
    }
}

