import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;

/**
 * Per-user persistence for {@link Task} objects.
 *
 * <p><b>File location:</b> one file per user at {@code data/<username>_tasks.txt}, so
 * each user's tasks are completely isolated. The file is created on first save.</p>
 *
 * <p><b>Storage format:</b> one task per line, six fields separated by a TAB character
 * in this order:</p>
 * <pre>
 *   id&lt;TAB&gt;status(Pending|Completed)&lt;TAB&gt;createdAt&lt;TAB&gt;updatedAt&lt;TAB&gt;title&lt;TAB&gt;description
 * </pre>
 * <p>Backslashes, tabs and newlines inside titles/descriptions are escaped as
 * {@code \\}, {@code \t} and {@code \n} so a title may safely contain almost any
 * character. Timestamps use the {@code yyyy-MM-dd HH:mm:ss} pattern. Blank and
 * comment ({@code #}) lines are ignored, so a stray partial line never crashes the app.</p>
 *
 * <p><b>ID generation strategy:</b> ids are sequential positive integers scoped to a
 * single user. Each call to {@link #addTask} uses {@code maxExistingId + 1}; because the
 * store is reloaded from disk on login, ids remain unique across program restarts
 * without a separate counter file. Deleting a task does not reuse its id.</p>
 */
public class TaskStore {

    /** Timestamp pattern used for created/updated fields. */
    private static final DateTimeFormatter TIMESTAMP =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    /** Field separator inside the task file. */
    private static final String SEP = "\t";

    private final String filePath;
    private final String owner;
    private final List<Task> tasks = new ArrayList<Task>();

    public TaskStore(String filePath, String owner) {
        this.filePath = filePath;
        this.owner = owner;
    }

    /** Human-readable owner of this store (the logged-in username). */
    public String getOwner() {
        return owner;
    }

    /** Loads tasks from disk (no-op when the file does not exist yet). */
    public void load() {
        tasks.clear();
        File file = new File(filePath);
        if (!file.exists()) {
            return;
        }
        BufferedReader reader = null;
        try {
            reader = new BufferedReader(new FileReader(file));
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.trim().isEmpty() || line.startsWith("#")) {
                    continue;
                }
                String[] parts = split(line);
                if (parts.length < 6) {
                    continue;
                }
                try {
                    int id = Integer.parseInt(parts[0].trim());
                    String status = unescape(parts[1]);
                    String createdAt = unescape(parts[2]);
                    String updatedAt = unescape(parts[3]);
                    String title = unescape(parts[4]);
                    String description = unescape(parts[5]);
                    tasks.add(new Task(id, title, description, createdAt, updatedAt, status));
                } catch (NumberFormatException e) {
                    // Skip malformed records rather than crashing.
                }
            }
        } catch (IOException e) {
            System.out.println("Warning: could not read task file: " + e.getMessage());
        } finally {
            closeQuietly(reader);
        }
    }

    /** @return an unmodifiable snapshot of the user's tasks. */
    public List<Task> getTasks() {
        return tasks;
    }

    /**
     * Creates a task with the next sequential id and persists it.
     *
     * @return the created task, or null if the title is empty or saving failed.
     */
    public Task addTask(String title, String description) {
        if (title == null || title.trim().isEmpty()) {
            return null;
        }
        String now = LocalDateTime.now().format(TIMESTAMP);
        Task task = new Task(nextId(), title.trim(), description == null ? "" : description,
                now, now, Task.STATUS_PENDING);
        tasks.add(task);
        if (!save()) {
            tasks.remove(task);
            return null;
        }
        return task;
    }

    /** @return the task with the given id, or null when not present. */
    public Task findById(int id) {
        for (Task task : tasks) {
            if (task.getId() == id) {
                return task;
            }
        }
        return null;
    }

    /** Marks a task completed, updating its timestamp, and persists the change. */
    public boolean markCompleted(int id) {
        Task task = findById(id);
        if (task == null) {
            return false;
        }
        task.setStatus(Task.STATUS_COMPLETED);
        task.setUpdatedAt(LocalDateTime.now().format(TIMESTAMP));
        return save();
    }

    /** Deletes a task by id and persists the removal. */
    public boolean delete(int id) {
        Task task = findById(id);
        if (task == null) {
            return false;
        }
        tasks.remove(task);
        return save();
    }

    /** @return the next unused id (max existing id + 1, or 1 when empty). */
    private int nextId() {
        int max = 0;
        for (Task task : tasks) {
            if (task.getId() > max) {
                max = task.getId();
            }
        }
        return max + 1;
    }

    /** Rewrites the whole task list to disk. */
    private boolean save() {
        File dir = new File("data");
        if (!dir.exists() && !dir.mkdirs() && !dir.exists()) {
            System.out.println("Error: could not create data directory.");
            return false;
        }
        BufferedWriter writer = null;
        try {
            writer = new BufferedWriter(new FileWriter(filePath));
            for (Task task : tasks) {
                writer.write(task.getId() + SEP
                        + escape(task.getStatus()) + SEP
                        + escape(task.getCreatedAt()) + SEP
                        + escape(task.getUpdatedAt()) + SEP
                        + escape(task.getTitle()) + SEP
                        + escape(task.getDescription()));
                writer.newLine();
            }
            writer.flush();
            return true;
        } catch (IOException e) {
            System.out.println("Error: could not save tasks: " + e.getMessage());
            return false;
        } finally {
            closeQuietly(writer);
        }
    }

    /** Splits a record on unescaped tabs. */
    private static String[] split(String line) {
        List<String> fields = new ArrayList<String>();
        StringBuilder current = new StringBuilder();
        boolean escaped = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (escaped) {
                current.append('\\').append(c);
                escaped = false;
            } else if (c == '\\') {
                escaped = true;
            } else if (c == '\t') {
                fields.add(current.toString());
                current.setLength(0);
            } else {
                current.append(c);
            }
        }
        if (escaped) {
            current.append('\\');
        }
        fields.add(current.toString());
        return fields.toArray(new String[0]);
    }

    private static String escape(String value) {
        if (value == null) {
            return "";
        }
        return value.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n");
    }

    private static String unescape(String value) {
        if (value == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        boolean escaped = false;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (escaped) {
                if (c == 't') {
                    sb.append('\t');
                } else if (c == 'n') {
                    sb.append('\n');
                } else {
                    sb.append(c);
                }
                escaped = false;
            } else if (c == '\\') {
                escaped = true;
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    private static void closeQuietly(java.io.Closeable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (IOException ignored) {
                // Nothing sensible to do on close failure.
            }
        }
    }
}

