import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * A single task belonging to a user in the Task Management System.
 *
 * <p>Besides the original fields (id, title, description, timestamps, status), a task
 * now carries advanced attributes: a {@code priority} of High/Medium/Low, an optional
 * {@code deadline} (stored as {@code yyyy-MM-dd}), and a list of {@code tags}.</p>
 *
 * <p>Tasks loaded from older storage files that predate these attributes are given
 * sensible defaults: priority {@code Medium}, empty deadline, and no tags.</p>
 */
public class Task {

    /** Status value for a task that still needs to be done. */
    public static final String STATUS_PENDING = "Pending";

    /** Status value for a finished task. */
    public static final String STATUS_COMPLETED = "Completed";

    /** Default priority assigned when none is supplied. */
    public static final String DEFAULT_PRIORITY = "Medium";

    private final int id;
    private String title;
    private String description;
    private String createdAt;
    private String updatedAt;
    private String status;
    private String priority;
    private String deadline;
    private final List<String> tags = new ArrayList<String>();

    public Task(int id, String title, String description, String createdAt,
                String updatedAt, String status) {
        this(id, title, description, createdAt, updatedAt, status,
                DEFAULT_PRIORITY, "", Collections.<String>emptyList());
    }

    public Task(int id, String title, String description, String createdAt,
                String updatedAt, String status, String priority, String deadline,
                List<String> tags) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.createdAt = createdAt;
        this.updatedAt = updatedAt;
        this.status = status;
        this.priority = (priority == null || priority.trim().isEmpty())
                ? DEFAULT_PRIORITY : priority.trim();
        this.deadline = deadline == null ? "" : deadline.trim();
        if (tags != null) {
            for (String tag : tags) {
                if (tag != null && !tag.trim().isEmpty()) {
                    this.tags.add(tag.trim());
                }
            }
        }
    }

    public int getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getCreatedAt() {
        return createdAt;
    }

    public String getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(String updatedAt) {
        this.updatedAt = updatedAt;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public boolean isCompleted() {
        return STATUS_COMPLETED.equalsIgnoreCase(status);
    }

    public String getPriority() {
        return priority;
    }

    public void setPriority(String priority) {
        this.priority = (priority == null || priority.trim().isEmpty())
                ? DEFAULT_PRIORITY : priority.trim();
    }

    public String getDeadline() {
        return deadline;
    }

    public void setDeadline(String deadline) {
        this.deadline = deadline == null ? "" : deadline.trim();
    }

    /** @return a live view of the task's tags. */
    public List<String> getTags() {
        return tags;
    }

    /** @return true when the task has the given tag (case-insensitive). */
    public boolean hasTag(String tag) {
        if (tag == null) {
            return false;
        }
        for (String existing : tags) {
            if (existing.equalsIgnoreCase(tag.trim())) {
                return true;
            }
        }
        return false;
    }

    /** @return the tags as a comma-separated string (or empty). */
    public String getTagsAsString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tags.size(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(tags.get(i));
        }
        return sb.toString();
    }
}

