/** Filters the current user's tasks by one or more key=[secret redacted]
private void filterTasks(TaskStore taskStore, String[] tokens) {
    List<Task> matching = new ArrayList<Task>();
    boolean hasCriteria = false;
    for (int i = 1; i < tokens.length; i++) {
        String criterion = tokens[i];
        int eq = criterion.indexOf('=');
        if (eq <= 0) {
            System.out.println("Invalid filter: " + criterion
                    + " (expected key=[secret redacted]
            return;
        }
        hasCriteria = true;
    }
    if (!hasCriteria) {
        System.out.println("Usage: /filter priority=high | /filter tag=work | "
                + "/filter status=pending | /filter deadline=2026-01-10 | /filter title=report");
        return;
    }

    for (Task task : taskStore.getTasks()) {
        boolean matches = true;
        for (int i = 1; i < tokens.length && matches; i++) {
            String criterion = tokens[i];
            int eq = criterion.indexOf('=');
            String key = [secret redacted]
            String value = criterion.substring(eq + 1);
            matches = matchesCriterion(task, key, value);
        }
        if (matches) {
            matching.add(task);
        }
    }
    printTasks(matching, "Filtered Tasks");
}

private boolean matchesCriterion(Task task, String key, String value) {
    if ("priority".equals(key)) {
        return task.getPriority().equalsIgnoreCase(value);
    }
    if ("tag".equals(key) || "tags".equals(key)) {
        return task.hasTag(value);
    }
    if ("status".equals(key)) {
        return task.getStatus().equalsIgnoreCase(value);
    }
    if ("deadline".equals(key)) {
        return task.getDeadline().equalsIgnoreCase(value);
    }
    if ("title".equals(key)) {
        return task.getTitle().toLowerCase().contains(value);
    }
    return false;
}

/** Sorts and prints the current user's tasks by the given field. */
private void sortTasks(TaskStore taskStore, String field) {
    if (field == null || field.isEmpty()) {
        System.out.println("Usage: /sort deadline | /sort priority | /sort title");
        return;
    }
    List<Task> sorted = new ArrayList<Task>(taskStore.getTasks());
    if ("deadline".equals(field)) {
        Collections.sort(sorted, new Comparator<Task>() {
            public int compare(Task a, Task b) {
                LocalDate da = parseDate(a.getDeadline());
                LocalDate db = parseDate(b.getDeadline());
                if (da == null && db == null) {
                    return 0;
                }
                if (da == null) {
                    return 1; // tasks without a deadline sort last
                }
                if (db == null) {
                    return -1;
                }
                return da.compareTo(db);
            }
        });
    } else if ("priority".equals(field)) {
        Collections.sort(sorted, new Comparator<Task>() {
            public int compare(Task a, Task b) {
                return priorityRank(a.getPriority()) - priorityRank(b.getPriority());
            }
        });
    } else if ("title".equals(field)) {
        Collections.sort(sorted, new Comparator<Task>() {
            public int compare(Task a, Task b) {
                return a.getTitle().compareToIgnoreCase(b.getTitle());
            }
        });
    } else {
        System.out.println("Unknown sort field: " + field
                + " (expected deadline, priority or title)");
        return;
    }
    printTasks(sorted, "Sorted Tasks (by " + field + ")");
}

