/**
 * Case-insensitive partial full-text search across title and description.
 * Unlike the default list, this scans archived tasks too so hidden tasks remain
 * findable. Matching tasks are printed with their archive state.
 */
private void searchTasks(TaskStore taskStore, String query) {
    if (query == null || query.trim().isEmpty()) {
        System.out.println("Usage: /search <text>  (searches titles and descriptions)");
        return;
    }
    List<Task> matches = new ArrayList<Task>();
    for (Task task : taskStore.getTasks()) {
        if (task.matchesText(query)) {
            matches.add(task);
        }
    }
    System.out.println();
    System.out.println("===== Search Results for \"" + query.trim() + "\" =====");
    if (matches.isEmpty()) {
        System.out.println("No matching tasks found.");
        return;
    }
    for (Task task : matches) {
        System.out.println("Task ID: " + task.getId());
        System.out.println("Title: " + task.getTitle());
        System.out.println("Description: " + task.getDescription());
        System.out.println("Priority: " + task.getPriority());
        System.out.println("Deadline: " + (task.getDeadline().isEmpty() ? "(none)" : task.getDeadline()));
        System.out.println("Tags: " + (task.getTags().isEmpty() ? "(none)" : task.getTagsAsString()));
        System.out.println("Status: " + task.getStatus());
        System.out.println("Archived: " + (task.isArchived() ? "yes" : "no"));
        System.out.println("----------------------------------------");
    }
    System.out.println("Total matches: " + matches.size());
}

/**
 * Archives a task (hides it from the default list) but keeps it searchable.
 * The confirmation deliberately contains the word "hiding".
 */
private void archiveTaskFlow(TaskStore taskStore, String inlineId) {
    System.out.println();
    System.out.println("===== Archive Task =====");
    Integer id = resolveTaskId(inlineId, "Enter task ID to archive: ");
    if (id == null) {
        return;
    }
    Task task = taskStore.findById(id);
    if (task == null) {
        System.out.println("Task " + id + " not found.");
        return;
    }
    if (task.isArchived()) {
        System.out.println("Task " + id + " is already archived, hiding from main list");
        return;
    }
    if (taskStore.setArchived(id, true)) {
        System.out.println("Task " + id + " archived, hiding from main list");
    } else {
        System.out.println("Error: could not archive task " + id + ".");
    }
}

/** Restores an archived task to the default list. */
private void unarchiveTaskFlow(TaskStore taskStore, String inlineId) {
    System.out.println();
    System.out.println("===== Unarchive Task =====");
    Integer id = resolveTaskId(inlineId, "Enter task ID to unarchive: ");
    if (id == null) {
        return;
    }
    Task task = taskStore.findById(id);
    if (task == null) {
        System.out.println("Task " + id + " not found.");
        return;
    }
    if (!task.isArchived()) {
        System.out.println("Task " + id + " is not archived; it is visible again");
        return;
    }
    if (taskStore.setArchived(id, false)) {
        System.out.println("Task " + id + " unarchived, visible again in main list");
    } else {
        System.out.println("Error: could not unarchive task " + id + ".");
    }
}

