/** @return the snapshot of this user's tasks as serialized records. */
public List<String> snapshotRecords() {
    List<String> records = new ArrayList<String>();
    for (Task task : tasks) {
        records.add(serialize(task));
    }
    return records;
}

/**
 * Rewrites the whole task list to disk atomically while holding a file lock, then
 * mirrors the user's tasks into the shared multi-user database (also lock-guarded).
 */
private boolean save() {
    File dir = new File("data");
    if (!dir.exists() && !dir.mkdirs() && !dir.exists()) {
        System.out.println("Error: could not create data directory.");
        return false;
    }
    Boolean ok = StorageLock.withLock(lockFilePath(), "task file " + filePath,
            new StorageLock.Action<Boolean>() {
                public Boolean run() throws IOException {
                    writeAtomically(filePath, snapshotRecords());
                    return Boolean.TRUE;
                }
            });
    if (ok == null || !ok.booleanValue()) {
        return false;
    }
    // Keep the shared database in sync; it takes its own lock.
    SharedTaskDatabase.writeUserTasks(owner, snapshotRecords());
    return true;
}

/** Serializes a single task into the TAB-separated field record. */
private static String serialize(Task task) {
    return task.getId() + SEP
            + escape(task.getStatus()) + SEP
            + escape(task.getCreatedAt()) + SEP
            + escape(task.getUpdatedAt()) + SEP
            + escape(task.getTitle()) + SEP
            + escape(task.getDescription()) + SEP
            + escape(task.getPriority()) + SEP
            + escape(task.getDeadline()) + SEP
            + escape(task.getTagsAsString()) + SEP
            + (task.isArchived() ? "true" : "false");
}

/** Writes lines to a temp file then atomically moves it into place. */
private static void writeAtomically(String path, List<String> lines) throws IOException {
    Path target = Paths.get(path);
    Path parent = target.toAbsolutePath().getParent();
    if (parent != null) {
        Files.createDirectories(parent);
    }
    Path tmp = Paths.get(path + ".tmp");
    BufferedWriter writer = new BufferedWriter(new FileWriter(tmp.toFile()));
    try {
        for (String line : lines) {
            writer.write(line);
            writer.newLine();
        }
        writer.flush();
    } finally {
        closeQuietly(writer);
    }
    try {
        Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING,
                StandardCopyOption.ATOMIC_MOVE);
    } catch (IOException e) {
        Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
    }
}

/** @return the lock file path used to serialize writes to this user's task file. */
private String lockFilePath() {
    return filePath + ".lock";
}

