public static void main(String[] args) {
    UserStore store = new UserStore(USERS_FILE);
    // Reload persisted users so previously registered accounts can log in.
    store.load();

    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    Main app = new Main(store, reader);

    String user = parseUserArgument(args);
    if (user != null && !user.trim().isEmpty()) {
        // Non-interactive / multi-terminal mode: operate directly as this user so
        // several processes can run concurrently against the shared storage.
        app.currentUser = user.trim();
        System.out.println("[INFO] Starting session for user '" + app.currentUser
                + "' (--user mode; shared storage, lock-guarded)");
        app.authenticatedMenu();
        System.out.println("Goodbye");
    } else {
        app.run();
    }
}

/** Parses {@code --user <name>} or {@code --user=<name>} from the command line. */
private static String parseUserArgument(String[] args) {
    if (args == null) {
        return null;
    }
    for (int i = 0; i < args.length; i++) {
        String arg = args[i];
        if ("--user".equals(arg) && i + 1 < args.length) {
            return args[i + 1];
        }
        if (arg != null && arg.startsWith("--user=")) {
            return arg.substring("--user=".length());
        }
    }
    return null;
}

